import sys
import flax.linen as nn
import jax.numpy as jnp
import optax
sys.path.append('storage/episteme')
from fourier_film_v2_simplified import FourierFiLMSimplified

def compute_loss(predictions, targets, params, x, mutable_vars):
    # Base Loss (from SOTA)
    mae = jnp.mean(jnp.abs(predictions - targets))
    curv = predictions[:, 2:, :] - 2.0 * predictions[:, 1:-1, :] + predictions[:, :-2, :]
    curv_pen = jnp.mean(curv * curv)
    base_loss = mae + 1e-4 * curv_pen

    # New L2 Regularization for FiLM parameters
    gamma = mutable_vars['intermediates']['gamma'][0]
    beta = mutable_vars['intermediates']['beta'][0]
    film_reg = jnp.mean(gamma**2) + jnp.mean(beta**2)

    return base_loss + 1e-5 * film_reg

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adam(learning_rate=learning_rate)
    )

def _define_hyperparameters():
    return { 'learning_rate': 0.001, 'rank_k': 320, 'proj_rank': 32 }

def create_network(hparams):
    class ModelWrapper:
        def __init__(self, hparams):
            self.model = FourierFiLMSimplified(rank_k=hparams['rank_k'], proj_rank=hparams['proj_rank'])
            self.needs_rng = True
            self.mutable = ['intermediates'] # Make sow() collections mutable
        def init(self, rng_key, dummy_input):
            return self.model.init({'params': rng_key, 'dropout': rng_key}, dummy_input)
        def apply(self, params, x, training=False, rngs=None, mutable=None):
            if mutable:
                return self.model.apply(params, x, training=training, rngs=rngs, mutable=mutable)
            return self.model.apply(params, x, training=training, rngs=rngs)
    return ModelWrapper(hparams)

